@gql_node_type(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description=(
            "A file written into every session of a domain, a project or a user. Only the "
            "default of a path is written."
        ),
    ),
    name="AutoGeneratedFile",
)
class AutoGeneratedFileGQL(PydanticNodeMixin[AutoGeneratedFileNodeDTO]):
    id: NodeID[str] = gql_field(description="Relay-style global node identifier.")
    entity_id: UUID = gql_field(description="ID of the auto-generated file.")
    scope_type: AutoGeneratedFileScopeTypeGQL = gql_field(
        description="Kind of the scope the file belongs to."
    )
    scope_id: UUID = gql_field(description="ID of the domain, project or user.")
    path: str = gql_field(description="Path the file is written to in a session.")
    is_default: bool = gql_field(description="Whether the file is the default of its path.")
    created_at: datetime = gql_field(description="Creation timestamp.")
    updated_at: datetime = gql_field(description="Last update timestamp.")

    @classmethod
    @override
    async def resolve_nodes(
        cls,
        *,
        info: Info[StrawberryGQLContext, Any],
        node_ids: Iterable[str],
        required: bool = False,
    ) -> Iterable[Self]:
        raise NotImplementedAPI("Auto-generated file node resolution is not implemented.")


AutoGeneratedFileEdgeGQL = Edge[AutoGeneratedFileGQL]


@gql_connection_type(
    BackendAIGQLMeta(
        added_version=NEXT_RELEASE_VERSION,
        description="Paginated connection for auto-generated files.",
    ),
    name="AutoGeneratedFileConnection",
)
class AutoGeneratedFileConnectionGQL(Connection[AutoGeneratedFileGQL]):
    count: int = gql_field(description="Total number of files matching the query.")

    def __init__(self, *args: Any, count: int, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.count = count


